"""Bind observed fixed-package outputs. Does not run tests or invent passes."""
from pathlib import Path
import hashlib,json
R=Path(__file__).resolve().parents[3];D=R/'artifacts/salvage-port-v04';h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def record(p):return {'path':str(p.relative_to(R)),'bytes':p.stat().st_size,'sha256':h(p)}
def write(p,j):p.write_text(json.dumps(j,ensure_ascii=False,indent=2)+'\n')
b=json.load(open(D/'build-info.json'));browser=json.load(open(D/'developer/browser-results.json'));assert browser['stats']['unexpected']==0 and browser['stats']['expected']==72
cap=D/'developer/capture';r=json.load(open(cap/'capture-report.json'));assert r['completed'] and r['build']['commit']==b['sourceCommit']
media=[record(p)for p in sorted(cap.rglob('*'))if p.is_file() and p.name!='manifest.json'];write(cap/'manifest.json',{'runtimeSourceSha':b['sourceCommit'],'zipSha256':b['sha256'],'report':str((cap/'capture-report.json').relative_to(R)),'natural':'Two new-game real elapsed voyages, no imports/seed/time override','qa':'Explicit27049 copy; purchase/equip/upgrade/supply, separate recording','physicalPhone':False,'files':media})
receipt=json.load(open(D/'taptap-receipt.json'));http=json.load(open(D/'package-http.json'));files=[record(p)for p in sorted(D.rglob('*'))if p.is_file() and p.name!='verification.json'];write(D/'verification.json',{'schema':4,'runtimeSourceSha':b['sourceCommit'],'buildInfo':str((D/'build-info.json').relative_to(R)),'zip':{'path':str((D/b['archive']).relative_to(R)),'filename':b['archive'],'bytes':b['bytes'],'sha256':b['sha256'],'files':b['files'],'dirty':False},'packageFiles':http['files'],'httpReport':str((D/'package-http.json').relative_to(R)),'fixedPackageBrowser':{'runtimeSourceSha':b['sourceCommit'],'zipSha256':b['sha256'],'expected':72,'unexpected':0,'skipped':0,'flaky':0,'retries':0,'report':str((D/'developer/browser-results.json').relative_to(R))},'capture':{'manifest':str((cap/'manifest.json').relative_to(R))},'platform':{'status':'UPLOADED_DEVELOPMENT_SELF_TEST','currentPackageId':receipt['taptap']['package_id'],'previousPackageId':454472,'formalBound':False,'releasing':False,'receipt':str((D/'taptap-receipt.json').relative_to(R))},'physicalPhone':'NOT_TESTED','userArt':'PENDING','humanEnjoyment':'PENDING','evidenceFiles':files})
print('Bound',len(files),'observed files to',b['sourceCommit'],b['sha256'])
